#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine;
namespace LastRail.Tests.EditMode {
 // Explicit fixture D/geometry, no augment ID, owned source or trial critical-policy claim.
 public sealed class PierceV3FlightTests {
  static string Hash(JToken p)=>BDirectAttackInput.Digest(p);
  static JObject N(int n)=>new JObject{["numerator"]=n.ToString(),["denominator"]="1"};
  static JObject Attack(int n=100)=>new JObject{["version"]=CombatProjectileAttackSnapshot.Version,["completedAttack"]=N(n),["appliedOffense"]=new JArray(),["penetration"]=new JArray()};
  static JObject Defense(int n=0)=>new JObject{["version"]=CombatProjectileAttackSnapshot.Version,["defense"]=N(n),["effects"]=new JArray(),["weakening"]=new JArray(),["reductions"]=new JObject{["equipment"]=new JArray(),["guardStance"]=new JArray(),["independent"]=new JArray()}};
  static JObject Target(string id,long x,long z=0)=>new JObject{["id"]=id,["generation"]=1,["eligible"]=true,["slot"]=0,["domain"]="TEST_ROOF",["feetMm"]=new JArray(x,0,z),["anchorMm"]=new JArray(x,1100,z),["heightMm"]=1700,["radiusMm"]=300};
  static JObject Observation(){var profile=JObject.Parse(File.ReadAllText(Path.Combine(Application.dataPath,"_LASTRAIL/Data/Combat/MiraJudgementProfileV1.json")));var basis=new JObject{["fixture"]=true};return new JObject{["version"]=MiraJudgementSceneAdapter.ObservationVersion,["profile"]=profile,["profileHash"]=Hash(profile),["basis"]=basis,["basisHash"]=Hash(basis),["layoutHash"]="EXPLICIT_FIXTURE",["tick"]=0,["revision"]=1,["source"]=new JObject{["id"]="op_mira",["generation"]=1,["slot"]=0,["domain"]="TEST_ROOF",["muzzleMm"]=new JArray(0,1100,0)},["targets"]=new JArray(Target("a",3000),Target("b",6000),Target("c",9000),Target("d",12000),Target("side",3000,2000)),["blockers"]=new JArray()};}
  static JObject Frame(JObject p,int tick=1){var q=(JObject)p.DeepClone();q["tick"]=tick;q["revision"]=tick+1;return q;}
  static JObject Row(JObject p,string id)=>(JObject)((JArray)p["targets"]).Single(t=>(string)t["id"]==id);
  static void Move(JObject p,string id,int x,int z=0){var r=Row(p,id);r["feetMm"]=new JArray(x,0,z);r["anchorMm"]=new JArray(x,1100,z);}
  static Type Type(string name){var t=typeof(FriendlyProjectileOwner).Assembly.GetType("LastRail.Battle."+name);Assert.That(t,Is.Not.Null,name+" missing");return t;}
  static object Invoke(object o,string name,params object[] args){try{return o.GetType().GetMethod(name).Invoke(o,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static object Static(string type,string name,params object[] args){try{return Type(type).GetMethod(name).Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static object Flight(JObject p,int capacity=128)=>Static("MiraPierceFlight","Create","fixture-combat","o",p,Hash(p),new JArray("a"),Attack(),capacity);
  static JArray Step(object f,JObject end,long us=500000,Func<string,JObject> arrival=null)=>(JArray)Invoke(f,"Step",end,Hash(end),us,arrival??(_=>Defense()));
  static JObject Capture(object f)=>(JObject)Invoke(f,"Capture");
  static object Restore(object f){var p=JObject.Parse(Capture(f).ToString());return Static("MiraPierceFlight","Restore",p,"fixture-combat",Hash(p));}
  [Test]public void BehindCapsulesReserveTwoAndExcludeBeforeSelectingEn17Sides(){var p=Observation();var f=Flight(p);var plan=Capture(f)["reservation"];Assert.That(plan["contacts"].Select(t=>(string)t["targetId"]),Is.EqualTo(new[]{"a","b","c"}));Assert.That(plan["excludedTargetIds"].Values<string>(),Is.EquivalentTo(new[]{"a","b","c"}));var hits=Step(f,Frame(p));Assert.That(hits.Select(t=>(int)t["contact"]["damage"]),Is.EqualTo(new[]{100,60,30}));}
  [Test]public void SameProjectionOverlappingAndEarlierContactDoNotCountAsBehind(){var p=Observation();Move(p,"b",3000);Move(p,"c",3100);Row(p,"c")["radiusMm"]=800;var f=Flight(p);Assert.That(Capture(f)["reservation"]["contacts"].Select(t=>(string)t["targetId"]),Is.EqualTo(new[]{"a","d"}));}
  [Test]public void MovingSecondReservationContactsFirstForThirtyThenFirstForSixty(){var p=Observation();var f=Flight(p);var end=Frame(p);Move(end,"b",18000);Move(end,"c",4000);var hits=Step(f,end);Assert.That(hits.Select(t=>(string)t["contact"]["targetId"]),Is.EqualTo(new[]{"a","c","b"}));Assert.That(hits.Select(t=>(int)t["contact"]["damage"]),Is.EqualTo(new[]{100,30,60}));Assert.That(hits.Select(t=>(int)t["contact"]["ordinal"]),Is.EqualTo(new[]{0,2,1}));Assert.That(JToken.DeepEquals(Capture(f),Capture(Restore(f))),Is.True);}
  [Test]public void MainAndFirstReservationLossDoNotPromoteOrRetargetTheLast(){var p=Observation();var f=Flight(p);var end=Frame(p);Row(end,"a")["eligible"]=false;Row(end,"b")["generation"]=2;var hits=Step(f,end);Assert.That(hits.Where(t=>(string)t["contact"]["outcome"]=="HIT").Select(t=>(string)t["contact"]["targetId"]),Is.EqualTo(new[]{"c"}));Assert.That((int)hits.Single(t=>(string)t["contact"]["targetId"]=="c")["contact"]["damage"],Is.EqualTo(30));}
  [TestCase(4500,100)][TestCase(7500,160)]public void MovingWallTerminatesRemainingSameFlightEvenIfMainDisappears(int x,int expected){var p=Observation();((JArray)p["blockers"]).Add(new JObject{["id"]="wall",["centerMm"]=new JArray(20000,1100,0),["sizeMm"]=new JArray(200,2000,2000)});var f=Flight(p);var begin=Frame(p);begin["blockers"][0]["centerMm"]=new JArray(x,1100,0);Step(f,begin,0);var end=Frame(begin,2);var hits=Step(f,end);Assert.That(hits.Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(expected));Assert.That((string)Capture(f)["flight"]["state"]["opportunities"][0]["branches"][0]["status"],Is.EqualTo("INTERRUPTED"));}
  [Test]public void CumulativeDistanceHoldAndPartitionedRestoreNeverRestartAtMainHit(){var p=Observation();var f=Flight(p);var first=Step(f,Frame(p),100000);Assert.That(first.Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(100));Invoke(f,"SetHeld",true);var frozen=Capture(f);Assert.That(Step(f,Frame(p,2),200000).Count,Is.Zero);Assert.That(JToken.DeepEquals(frozen,Capture(f)),Is.True);Invoke(f,"SetHeld",false);var restored=Restore(f);var end=Frame(p,2);Assert.That(JToken.DeepEquals(Step(f,end,500000),Step(restored,end,500000)),Is.True);Assert.That(JToken.DeepEquals(Capture(f),Capture(restored)),Is.True);Assert.That(Step(f,Frame(p,3),500000).Count,Is.Zero);}
  [Test]public void ArrivalDefenseAndNativeShieldHpDoNotBecomeNextTargetBudget(){var p=Observation();var f=Flight(p);var hits=Step(f,Frame(p),500000,id=>Defense(id=="b"?1000:0));var vitals=new CombatVitals(10,10000);vitals.Shield(new CombatShieldSource("fixture","skill",0),5,10,0);var damage=(int)hits.Single(t=>(string)t["contact"]["targetId"]=="b")["contact"]["damage"];Assert.That(damage,Is.EqualTo(30));var hp=vitals.Damage(damage,1,false);Assert.That(hp.Absorbed,Is.EqualTo(5));Assert.That(hp.HpLoss,Is.EqualTo(10));Assert.That((int)hits.Single(t=>(string)t["contact"]["targetId"]=="c")["contact"]["damage"],Is.EqualTo(30));}
  [Test]public void LostMainStillDetectsWallAndDoesNotPassDamageBehindIt(){var p=Observation();((JArray)p["blockers"]).Add(new JObject{["id"]="wall",["centerMm"]=new JArray(20000,1100,0),["sizeMm"]=new JArray(200,2000,2000)});var f=Flight(p);var begin=Frame(p);begin["blockers"][0]["centerMm"]=new JArray(4500,1100,0);Row(begin,"a")["eligible"]=false;Step(f,begin,0);var hits=Step(f,Frame(begin,2));Assert.That(hits.Sum(t=>(int)t["contact"]["damage"]),Is.Zero);Assert.That((bool)Capture(f)["stopped"],Is.True);}
  [Test]public void UnreservedEnemyEnteringRayAndNewSourcePoseCannotRedirectFrozenFlight(){var p=Observation();var f=Flight(p);var end=Frame(p);Move(end,"d",1000);end["source"]["muzzleMm"]=new JArray(20000,1100,0);var hits=Step(f,end);Assert.That(hits.Select(t=>(string)t["contact"]["targetId"]),Is.EqualTo(new[]{"a","b","c"}));Assert.That(hits.Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(190));}
  [Test]public void EqualCollisionDistanceUsesStableIdAndSharedHpIdentityCannotDuplicate(){var p=Observation();Move(p,"c",6000);Move(p,"d",6000);var f=Flight(p);Assert.That(Capture(f)["reservation"]["contacts"].Select(t=>(string)t["targetId"]),Is.EqualTo(new[]{"a","b","c"}));((JArray)p["targets"]).Add(Row(p,"b").DeepClone());Assert.Throws<ArgumentException>(()=>Flight(p));}
  [Test]public void CheckpointIndependentPinAndRebuiltReservationRejectTampering(){var f=Flight(Observation());var snap=Capture(f);snap["reservation"]["contacts"][1]["coefficientBps"]=10000;Assert.Throws<ArgumentException>(()=>Static("MiraPierceFlight","Restore",snap,"fixture-combat",Hash(Capture(f))));Assert.Throws<ArgumentException>(()=>Static("MiraPierceFlight","Restore",snap,"fixture-combat",Hash(snap)));}
  [Test]public void SameTickNoContactJournalCapacityRejectsAtomicallyAndRemainsRestorable(){var p=Observation();var f=Flight(p,2);Step(f,p,1000);Step(f,p,2000);Assert.That(JToken.DeepEquals(Capture(f),Capture(Restore(f))),Is.True);var before=Capture(f);Assert.Throws<InvalidOperationException>(()=>Step(f,p,3000));Assert.That(JToken.DeepEquals(before,Capture(f)),Is.True);Assert.That(JToken.DeepEquals(before,Capture(Restore(f))),Is.True);}
  [TestCase("INTERCEPTED")][TestCase("NODE_END")][TestCase("COMBAT_END")]public void OriginalTerminationStopsPendingReservationsAndReplaysWithoutHp(string reason){var p=Observation();var f=Flight(p);Step(f,Frame(p),100000);Assert.That(Invoke(f,"Stop",reason),Is.EqualTo(true));Assert.That(Invoke(f,"Stop",reason),Is.EqualTo(false));var before=Capture(f);Assert.That(Step(f,Frame(p,2)).Count,Is.Zero);Assert.That(JToken.DeepEquals(before,Capture(f)),Is.True);Assert.That(JToken.DeepEquals(before,Capture(Restore(f))),Is.True);}
  [TestCase(0,100)][TestCase(1,160)][TestCase(2,190)]public void ZeroOneTwoRearTargetsKeepOriginalDWithoutCreatingExtraOpportunities(int count,int expected){var p=Observation();var targets=(JArray)p["targets"];foreach(var t in targets.Where(t=>(string)t["id"]!="a"&&(string)t["id"]!="side").Skip(count).ToArray())t.Remove();var f=Flight(p);Assert.That(Step(f,Frame(p)).Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(expected));Assert.That(((JArray)Capture(f)["flight"]["state"]["opportunities"]).Count,Is.EqualTo(1));}
  [Test]public void MovingReservedEnemyCanMissWithoutPromotingTheSecondOrChoosingTheThird(){var p=Observation();var f=Flight(p);var end=Frame(p);Move(end,"b",6000,9000);var hits=Step(f,end);Assert.That(hits.Where(t=>(string)t["contact"]["outcome"]=="HIT").Select(t=>(string)t["contact"]["targetId"]),Is.EqualTo(new[]{"a","c"}));Assert.That(hits.Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(130));}
  [Test]public void RearCapsulesBeyondOriginalMaximumCannotCreateAnExtendedFlight(){var p=Observation();Move(p,"b",25000);Move(p,"c",26000);Move(p,"d",27000);var f=Flight(p);Assert.That(Step(f,Frame(p)).Sum(t=>(int)t["contact"]["damage"]),Is.EqualTo(100));Assert.That((long)Capture(f)["reservation"]["ray"]["maximumDistanceMm"],Is.EqualTo(24000));}
  [Test]public void FailedArrivalAndCapacityDoNotPartiallyPublishFlight(){var p=Observation();var f=Flight(p);var before=Capture(f);Assert.Throws<InvalidOperationException>(()=>Step(f,Frame(p),500000,id=>id=="b"?throw new InvalidOperationException("fixture failure"):Defense()));Assert.That(JToken.DeepEquals(before,Capture(f)),Is.True);var tiny=Flight(p,2);var original=Capture(tiny);Assert.Throws<InvalidOperationException>(()=>Step(tiny,Frame(p)));Assert.That(JToken.DeepEquals(original,Capture(tiny)),Is.True);}
 }
}
#endif